/**
 * The contract between the App Settings components and wherever settings
 * actually live.
 *
 * Everything in this directory is transport-agnostic on purpose. The components
 * talk to a {@link SettingsTransport}, so the same UI renders whether it is
 * pointed straight at an App Settings deployment with an API key or at your own
 * API standing in front of one.
 */

import type {
  ResolvedSetting,
  ResolveResponse,
  SettingType,
  SettingValue,
  ValueSource,
} from "app-settings-js";

export type {
  Override,
  ResolvedSetting,
  ResolveResponse,
  SelectOption,
  Setting,
  SettingScope,
  SettingType,
  SettingValue,
  TypeConfig,
  ValueSource,
} from "app-settings-js";

/** Which layer a write lands in. */
export type SettingLayer = "server" | "personal" | "group";

/** What to resolve. Every field falls back to the provider's own default. */
export interface ResolveQuery {
  /** The user to resolve for. Omitted means the server layer alone. */
  userId?: string;
  environment?: string;
  platform?: string | string[];
  /** Resolve as this role rather than the API key's own. */
  role?: string;
  /** Groups applied without stored membership, for previewing a policy. */
  groupId?: string | string[];
}

/**
 * One pending change to one setting.
 *
 * `value: undefined` means "clear this layer" rather than "write undefined",
 * which is the distinction between falling back to the layer beneath and
 * storing an empty value.
 */
export interface WriteRequest {
  /** The setting being written, so a transport can use its id, name or type. */
  setting: ResolvedSetting;
  /** The new value, or `undefined` to clear the layer. */
  value: SettingValue | undefined;
  layer: SettingLayer;
  /** Required by the `personal` layer. */
  userId?: string;
  /** Required by the `group` layer. */
  groupId?: string;
  /** `group` only: whether the user may observe the override. */
  visible?: boolean;
  /** `group` only: whether the override beats the user's own value. */
  enforced?: boolean;
}

/** Where settings are read from and written to. */
export interface SettingsTransport {
  /** Reads one resolution. The response shape is the API's own. */
  resolve(query: ResolveQuery, signal?: AbortSignal): Promise<ResolveResponse>;
  /**
   * Applies one write. Omit it for a read-only board: the components disable
   * their controls rather than offering an edit that cannot land.
   */
  write?(request: WriteRequest, signal?: AbortSignal): Promise<void>;
}

/** A control that renders one setting's value, for the type-to-input registry. */
export interface SettingInputProps<T = SettingValue> {
  setting: ResolvedSetting;
  value: T;
  onValueChange: (value: T) => void;
  /** The control is present but cannot be changed — enforced, or read-only. */
  disabled?: boolean;
  /** A write is in flight; the value shown is optimistic. */
  pending?: boolean;
  /** Wired to the field's label, so clicking the label focuses the control. */
  id?: string;
  /** Wired to the field's description and error text. */
  "aria-describedby"?: string;
  /** Set when {@link validateValue} rejected the current draft. */
  "aria-invalid"?: boolean;
  className?: string;
}

/**
 * The props of a setting input, minus the ones it owns.
 *
 * Every input in this set accepts the primitive's own props too, so a caller
 * can pass `placeholder`, `autoFocus` or a `data-*` attribute straight through
 * without the component having to enumerate them.
 */
export type SettingInputComponentProps<Value, PrimitiveProps> = Omit<
  PrimitiveProps,
  keyof SettingInputProps<Value> | "value" | "defaultValue" | "onChange" | "children"
> &
  SettingInputProps<Value>;

/** A validation failure raised locally, before a request goes out. */
export interface ValueProblem {
  /** Written for the person at the keyboard. */
  message: string;
  /** Which rule rejected the value, for branching or styling. */
  rule:
    | "type"
    | "min"
    | "max"
    | "integer"
    | "min_length"
    | "max_length"
    | "pattern"
    | "option"
    | "json";
}

/** The state one setting is in, as the field chrome needs to read it. */
export interface SettingStatus {
  source: ValueSource;
  type: SettingType;
  /** A group override shaped this value, and the user may know about it. */
  overridden: boolean;
  /** A group policy holds this value in place; writing it would do nothing. */
  enforced: boolean;
  /** No layer, not even the definition's default, supplied a value. */
  unset: boolean;
}

/**
 * Reading, checking and rendering setting values.
 *
 * Nothing here touches React or the network, which is what makes it testable
 * and what makes the components thin. The validation mirrors the rules the
 * server enforces in `type_config`, so a bad value is caught under the input
 * rather than after a round trip — the server is still the authority.
 */

import { isInstant, parseInstant, toDateTimeLocal } from "app-settings-js";

import type {
  Override,
  ResolvedSetting,
  ResolveResponse,
  SelectOption,
  SettingLayer,
  SettingStatus,
  SettingValue,
  TypeConfig,
  ValueProblem,
  ValueSource,
} from "@/registry/app-settings/lib/app-settings/types";

/** How each layer reads in a UI. */
export const SOURCE_LABELS: Record<ValueSource, string> = {
  UNSET: "Not set",
  DEFAULT: "Default",
  SERVER: "Server",
  INTERMEDIATE: "Group",
  PERSONAL: "Personal",
};

/** A human label for the layer an effective value came from. */
export function sourceLabel(source: ValueSource): string {
  return SOURCE_LABELS[source] ?? source;
}

/** Everything the field chrome needs to know about one setting's state. */
export function settingStatus(setting: ResolvedSetting): SettingStatus {
  const override = setting.override;
  return {
    source: setting.source,
    type: setting.type,
    overridden: override?.visible === true,
    enforced: override?.enforced === true,
    unset: setting.source === "UNSET",
  };
}

/** Whether a group policy is holding this value in place. */
export function isEnforced(setting: ResolvedSetting): boolean {
  return setting.override?.enforced === true;
}

/**
 * The override worth telling the user about.
 *
 * An override marked `visible: false` is deliberately withheld: the user is not
 * meant to observe that anything was overridden.
 */
export function visibleOverride(setting: ResolvedSetting): Override | undefined {
  return setting.override?.visible ? setting.override : undefined;
}

/** A one-line explanation of an override, for a badge title or helper text. */
export function describeOverride(override: Override): string {
  const verb = override.enforced ? "enforced by" : "set by";
  const replaced =
    override.enforced && override.replaced_value !== undefined
      ? `, replacing ${JSON.stringify(override.replaced_value)}`
      : "";
  return `This value is ${verb} group ${override.group_id}${replaced}.`;
}

/** The value a control should start from, with a type-appropriate empty. */
export function controlValue(setting: ResolvedSetting): SettingValue {
  if (setting.value !== null && setting.value !== undefined) return setting.value;
  return emptyValue(setting);
}

/** The value that stands for "nothing chosen yet" for a given type. */
export function emptyValue(setting: ResolvedSetting): SettingValue {
  switch (setting.type) {
    case "BOOLEAN":
      return false;
    case "NUMBER":
      return setting.type_config?.min ?? 0;
    case "STRING":
    case "DATETIME":
      return "";
    case "SELECT":
      return isMultiSelect(setting) ? [] : null;
    case "JSON":
      return null;
    default:
      return null;
  }
}

/** Whether a SELECT holds an array of options rather than one. */
export function isMultiSelect(setting: ResolvedSetting): boolean {
  return setting.type === "SELECT" && setting.type_config?.multiple === true;
}

/** The step a NUMBER input should use, honouring an `integer` constraint. */
export function numberStep(config: TypeConfig | undefined): number | "any" {
  return config?.integer ? 1 : "any";
}

/** One SELECT choice, with a string token safe to hand a `<Select>`. */
export interface SettingOption {
  label: string;
  value: SettingValue;
  /** A stable string form of `value`, since select elements only speak strings. */
  token: string;
}

/** The choices a SELECT offers. Empty for every other type. */
export function selectOptions(setting: ResolvedSetting): SettingOption[] {
  const options = setting.type_config?.options ?? [];
  return options.map(([label, value]: SelectOption) => ({
    label,
    value,
    token: optionToken(value),
  }));
}

/** The string form of an option value, used as a select token and React key. */
export function optionToken(value: SettingValue): string {
  return typeof value === "string" ? value : JSON.stringify(value ?? null);
}

/** The option a token came from, so a select change recovers the real value. */
export function optionFromToken(
  setting: ResolvedSetting,
  token: string,
): SettingOption | undefined {
  return selectOptions(setting).find((option) => option.token === token);
}

/** A multi-select value as an array, whatever shape the server sent. */
export function asArray(value: SettingValue): SettingValue[] {
  if (value === null || value === undefined) return [];
  return Array.isArray(value) ? value : [value];
}

/**
 * Checks a value against the setting's own rules.
 *
 * Returns `null` when the value is acceptable. These are the same rules the
 * server applies; running them here buys immediate feedback, not authority.
 */
export function validateValue(
  setting: ResolvedSetting,
  value: SettingValue,
): ValueProblem | null {
  const config = setting.type_config ?? {};

  switch (setting.type) {
    case "BOOLEAN":
      return typeof value === "boolean" ? null : problem("type", "Must be true or false.");

    case "NUMBER": {
      if (typeof value !== "number" || !Number.isFinite(value)) {
        return problem("type", "Must be a number.");
      }
      if (config.integer && !Number.isInteger(value)) {
        return problem("integer", "Must be a whole number.");
      }
      if (config.min !== undefined && value < config.min) {
        return problem("min", `Must be ${config.min} or more.`);
      }
      if (config.max !== undefined && value > config.max) {
        return problem("max", `Must be ${config.max} or less.`);
      }
      return null;
    }

    case "STRING": {
      if (typeof value !== "string") return problem("type", "Must be text.");
      if (config.min_length !== undefined && value.length < config.min_length) {
        return problem("min_length", `Must be at least ${config.min_length} characters.`);
      }
      if (config.max_length !== undefined && value.length > config.max_length) {
        return problem("max_length", `Must be at most ${config.max_length} characters.`);
      }
      if (config.pattern && !matchesPattern(value, config.pattern)) {
        return problem("pattern", `Must match ${config.pattern}.`);
      }
      return null;
    }

    case "DATETIME":
      return isInstant(value)
        ? null
        : problem("type", "Must be a date and time with a UTC offset.");

    case "SELECT": {
      const tokens = new Set(selectOptions(setting).map((option) => option.token));
      const chosen = isMultiSelect(setting) ? asArray(value) : [value];
      if (isMultiSelect(setting) && !Array.isArray(value)) {
        return problem("type", "Must be a list of choices.");
      }
      for (const candidate of chosen) {
        if (!tokens.has(optionToken(candidate))) {
          return problem("option", "Must be one of the offered choices.");
        }
      }
      return null;
    }

    case "JSON":
      return isJsonSerialisable(value) ? null : problem("json", "Must be JSON.");

    default:
      return null;
  }
}

/** Parses what a NUMBER input produced, without guessing at empty text. */
export function parseNumberInput(raw: string): number | undefined {
  if (raw.trim() === "") return undefined;
  const parsed = Number(raw);
  return Number.isFinite(parsed) ? parsed : undefined;
}

/** Parses a JSON textarea, reporting the parser's own complaint. */
export function parseJsonInput(
  raw: string,
): { ok: true; value: SettingValue } | { ok: false; problem: ValueProblem } {
  if (raw.trim() === "") return { ok: true, value: null };
  try {
    return { ok: true, value: JSON.parse(raw) as SettingValue };
  } catch (caught) {
    return {
      ok: false,
      problem: problem("json", caught instanceof Error ? caught.message : "Invalid JSON."),
    };
  }
}

/** Renders a JSON value for a textarea, stable enough to edit in place. */
export function formatJsonInput(value: SettingValue): string {
  if (value === null || value === undefined) return "";
  return JSON.stringify(value, null, 2);
}

/** Renders an instant for `<input type="datetime-local">`, in the local zone. */
export function formatDateTimeInput(value: SettingValue, timeZone?: string): string {
  if (typeof value !== "string" || value === "") return "";
  const parsed = parseInstant(value);
  return parsed ? toDateTimeLocal(parsed, timeZone) : "";
}

/**
 * A short, readable rendering of any value, for a summary row or a diff.
 *
 * A DATETIME is shown in the reader's own zone; everything else is shown as it
 * is stored, because a settings board is where the stored value matters.
 */
export function formatValue(setting: ResolvedSetting, value = setting.value): string {
  if (setting.source === "UNSET" && value === null) return "—";
  if (value === null || value === undefined) return "null";

  switch (setting.type) {
    case "BOOLEAN":
      return value ? "On" : "Off";
    case "DATETIME": {
      const parsed = typeof value === "string" ? parseInstant(value) : undefined;
      return parsed ? parsed.toLocaleString() : String(value);
    }
    case "SELECT": {
      const options = selectOptions(setting);
      const labelFor = (candidate: SettingValue) =>
        options.find((option) => option.token === optionToken(candidate))?.label ??
        String(candidate);
      return isMultiSelect(setting)
        ? asArray(value).map(labelFor).join(", ") || "—"
        : labelFor(value);
    }
    case "JSON":
      return JSON.stringify(value);
    default:
      return String(value);
  }
}

/** Whether two values are the same as far as a write is concerned. */
export function valuesEqual(a: SettingValue, b: SettingValue): boolean {
  if (a === b) return true;
  if (a === null || b === null || a === undefined || b === undefined) return false;
  if (typeof a !== "object" && typeof b !== "object") return false;
  return JSON.stringify(a) === JSON.stringify(b);
}

function problem(rule: ValueProblem["rule"], message: string): ValueProblem {
  return { rule, message };
}

/**
 * The server anchors patterns to the whole value and reads them as RE2. A
 * pattern RE2 accepts but JavaScript does not is treated as passing here, so a
 * local check never blocks a value the server would take.
 */
function matchesPattern(value: string, pattern: string): boolean {
  try {
    return new RegExp(`^(?:${pattern})$`, "u").test(value);
  } catch {
    return true;
  }
}

function isJsonSerialisable(value: SettingValue): boolean {
  if (value === null) return true;
  switch (typeof value) {
    case "boolean":
    case "string":
      return true;
    case "number":
      return Number.isFinite(value);
    case "object":
      try {
        JSON.stringify(value);
        return true;
      } catch {
        return false;
      }
    default:
      return false;
  }
}

/**
 * A resolution with one value replaced, leaving the original untouched.
 *
 * This is the optimistic update: show the new value at once, then let the next
 * resolution confirm it. A setting the resolution does not contain is left
 * alone rather than invented.
 */
export function withValue(
  response: ResolveResponse,
  name: string,
  value: SettingValue,
  source: ValueSource = "PERSONAL",
): ResolveResponse {
  let changed = false;
  const settings = (response.settings ?? []).map((setting) => {
    if (setting.name !== name) return setting;
    changed = true;
    return { ...setting, value, source };
  });

  return changed ? { ...response, settings } : response;
}

/** The layer a write shows up as, for an optimistic value's `source`. */
export function sourceForLayer(layer: SettingLayer): ValueSource {
  switch (layer) {
    case "personal":
      return "PERSONAL";
    case "group":
      return "INTERMEDIATE";
    case "server":
      return "SERVER";
    default:
      return "SERVER";
  }
}

/**
 * Turning a flat resolution into the sections a settings page renders.
 *
 * A resolution arrives in the server's order, which is stable but not
 * meaningful to a reader. These helpers are what `<SettingList>` uses; they are
 * exported so a page can lay the same groups out its own way.
 */

import type { ResolvedSetting } from "@/registry/app-settings/lib/app-settings/types";

/** One rendered section. */
export interface SettingGroup {
  /** A stable key, also used as the heading when no `title` is given. */
  key: string;
  title: string;
  settings: ResolvedSetting[];
}

/**
 * How to split settings into sections.
 *
 * `prefix` reads a dotted name — `billing.currency` lands in "billing" — which
 * is how most deployments already organise their settings.
 */
export type GroupBy =
  | "none"
  | "prefix"
  | "platform"
  | "role"
  | "scope"
  | ((setting: ResolvedSetting) => string);

export interface GroupSettingsOptions {
  by?: GroupBy;
  /** The heading for settings the grouper returns nothing for. */
  fallbackTitle?: string;
  /** Overrides the heading for a given key. */
  titles?: Record<string, string>;
  /** Orders the sections. Unlisted keys keep their first-seen order, after these. */
  order?: string[];
}

/** Splits a resolution into sections, preserving the server's order within each. */
export function groupSettings(
  settings: readonly ResolvedSetting[],
  options: GroupSettingsOptions = {},
): SettingGroup[] {
  const { by = "none", fallbackTitle = "General", titles = {}, order = [] } = options;
  const grouper = resolveGrouper(by);
  const groups = new Map<string, SettingGroup>();

  for (const setting of settings) {
    const key = grouper(setting) || "";
    const existing = groups.get(key);
    if (existing) {
      existing.settings.push(setting);
      continue;
    }
    groups.set(key, {
      key: key || "__general__",
      title: titles[key] ?? (key ? titleCase(key) : fallbackTitle),
      settings: [setting],
    });
  }

  const sections = [...groups.values()];
  if (order.length === 0) return sections;

  const rank = new Map(order.map((key, index) => [key, index]));
  return sections.sort(
    (a, b) => (rank.get(a.key) ?? order.length) - (rank.get(b.key) ?? order.length),
  );
}

/** The name with its grouping prefix removed, for a heading-relative label. */
export function shortName(setting: ResolvedSetting): string {
  const index = setting.name.lastIndexOf(".");
  return index === -1 ? setting.name : setting.name.slice(index + 1);
}

/** A readable label for a setting, from its dotted or snake-cased name. */
export function settingLabel(setting: ResolvedSetting): string {
  return titleCase(shortName(setting));
}

function resolveGrouper(by: GroupBy): (setting: ResolvedSetting) => string {
  if (typeof by === "function") return by;

  switch (by) {
    case "prefix":
      return (setting) => {
        const index = setting.name.indexOf(".");
        return index === -1 ? "" : setting.name.slice(0, index);
      };
    case "platform":
      return (setting) => setting.platform;
    case "role":
      return (setting) => setting.role;
    case "scope":
      return (setting) => setting.scope;
    default:
      return () => "";
  }
}

function titleCase(value: string): string {
  return value
    .replace(/[._-]+/g, " ")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .trim()
    .replace(/\b\w/g, (character) => character.toUpperCase());
}

/**
 * Query keys for the App Settings cache.
 *
 * Every key is derived from the resolution query, so two components asking for
 * the same resolution share one request, and a write can invalidate exactly the
 * resolutions it could have changed.
 */

import type { QueryKey } from "@tanstack/react-query";

import type { ResolveQuery } from "@/registry/app-settings/lib/app-settings/types";

export const appSettingsKeys = {
  /** Everything this library caches. Invalidate to refetch all of it. */
  all: () => ["app-settings"] as const,

  /** Every resolution, whatever it was resolved for. */
  resolutions: () => [...appSettingsKeys.all(), "resolution"] as const,

  /** One resolution. Field order and array order never affect the key. */
  resolution: (query: ResolveQuery = {}): QueryKey =>
    [...appSettingsKeys.resolutions(), normaliseQuery(query)] as const,

  /** Setting definitions, for an editor that lists more than a resolution does. */
  definitions: (filters: Record<string, unknown> = {}): QueryKey =>
    [...appSettingsKeys.all(), "definitions", filters] as const,
};

/**
 * A canonical form of a query, so `{ userId: "a" }` and
 * `{ environment: undefined, userId: "a" }` are one cache entry rather than two.
 */
export function normaliseQuery(query: ResolveQuery): Record<string, string | string[]> {
  const entries: [string, string | string[]][] = [];

  if (query.userId) entries.push(["userId", query.userId]);
  if (query.environment) entries.push(["environment", query.environment]);
  if (query.role) entries.push(["role", query.role]);

  const platform = sortedList(query.platform);
  if (platform.length) entries.push(["platform", platform]);

  const groupId = sortedList(query.groupId);
  if (groupId.length) entries.push(["groupId", groupId]);

  return Object.fromEntries(entries.sort(([a], [b]) => a.localeCompare(b)));
}

function sortedList(value: string | string[] | undefined): string[] {
  if (value === undefined) return [];
  return [...(Array.isArray(value) ? value : [value])].sort();
}

/**
 * The configuration every hook and component reads.
 *
 * It is deliberately a plain context rather than a store: the transport and the
 * defaults change rarely, and React Query already owns the part that changes
 * often. `<AppSettingsProvider>` in `app-settings-provider.tsx` is what fills
 * this in.
 */

import { createContext, useContext } from "react";

import type {
  ResolveQuery,
  SettingLayer,
  SettingsTransport,
} from "@/registry/app-settings/lib/app-settings/types";

/** Per-query React Query options a caller may override. */
export interface SettingsQueryConfig {
  /** How long a resolution is considered fresh. Defaults to 30 seconds. */
  staleTime?: number;
  gcTime?: number;
  /** Re-resolve on an interval. Off by default. */
  refetchInterval?: number | false;
  refetchOnWindowFocus?: boolean;
  refetchOnMount?: boolean | "always";
  retry?: number | boolean;
}

export interface AppSettingsConfig {
  transport: SettingsTransport;
  /** Applied to every resolution a hook makes, unless the hook overrides it. */
  query: ResolveQuery;
  /** Which layer writes land in. */
  layer: SettingLayer;
  /** The group a `group`-layer write targets. */
  writeGroupId?: string;
  /** `group` layer: whether the user may observe the override. */
  visible?: boolean;
  /** `group` layer: whether the override beats the user's own value. */
  enforced?: boolean;
  /** Renders every control disabled, whatever the transport can do. */
  readOnly: boolean;
  /** Check values against `type_config` before writing. On by default. */
  validate: boolean;
  queryConfig: SettingsQueryConfig;
}

export const AppSettingsContext = createContext<AppSettingsConfig | null>(null);

/**
 * The configuration from the nearest provider.
 *
 * @throws if there is no `<AppSettingsProvider>` above this component, which is
 * a wiring mistake rather than a state worth rendering.
 */
export function useAppSettingsConfig(): AppSettingsConfig {
  const config = useContext(AppSettingsContext);
  if (!config) {
    throw new Error(
      "useAppSettingsConfig must be used inside <AppSettingsProvider>. " +
        "Wrap your settings page in it and give it a transport.",
    );
  }
  return config;
}

/** The configuration, or null outside a provider, for an optional integration. */
export function useOptionalAppSettingsConfig(): AppSettingsConfig | null {
  return useContext(AppSettingsContext);
}

/**
 * The two transports most boards need.
 *
 * {@link transportFromClient} points the UI straight at an App Settings
 * deployment, which is the internal-admin case: the page holds an API key and
 * talks to the API directly.
 *
 * {@link createHttpTransport} points it at your own API instead. As long as
 * your endpoints speak App Settings' resolution shape, every component and hook
 * works unchanged — your server keeps the API key, and the browser never sees
 * it.
 */

import type { AppSettingsClient } from "app-settings-js";

import type {
  ResolveQuery,
  ResolveResponse,
  SettingsTransport,
  WriteRequest,
} from "@/registry/app-settings/lib/app-settings/types";

/** Wraps an `AppSettingsClient` from `app-settings-js`. */
export function transportFromClient(client: AppSettingsClient): SettingsTransport {
  return {
    async resolve(query, signal) {
      const options = {
        environment: query.environment,
        platform: query.platform,
        role: query.role,
        groupId: query.groupId,
        signal,
      };
      const snapshot = query.userId
        ? await client.resolveUser(query.userId, options)
        : await client.resolveServer(options);
      return snapshot.toJSON();
    },

    async write(request, signal) {
      const { setting, value, layer } = request;
      const clearing = value === undefined;

      if (layer === "server") {
        await (clearing
          ? client.values.server.clear(setting.id, { signal })
          : client.values.server.set(setting.id, value, { signal }));
        return;
      }

      if (layer === "personal") {
        const userId = required(request.userId, "personal", "userId");
        await (clearing
          ? client.values.personal.clear(setting.id, userId, { signal })
          : client.values.personal.set(setting.id, userId, value, { signal }));
        return;
      }

      const groupId = required(request.groupId, "group", "groupId");
      await (clearing
        ? client.values.group.clear(setting.id, groupId, { signal })
        : client.values.group.set(setting.id, groupId, value, {
            visible: request.visible,
            enforced: request.enforced,
            signal,
          }));
    },
  };
}

/** One request, described rather than performed, so a caller can shape it. */
export interface HttpRequestSpec {
  url: string;
  method?: string;
  /** Serialised as JSON. Omit for a request with no body. */
  body?: unknown;
  headers?: Record<string, string>;
}

/** Either a bare URL or a full description of the request to make. */
export type HttpRoute<T> = string | ((input: T) => HttpRequestSpec | string);

export interface HttpTransportOptions {
  /**
   * Where a resolution comes from.
   *
   * A string is called with the query appended as `user_id`, `environment`,
   * `platform`, `role` and `group_id` parameters, which is what an endpoint
   * proxying App Settings usually wants. Pass a function for anything else.
   * The response body must be an App Settings resolution.
   */
  resolve: HttpRoute<ResolveQuery>;
  /**
   * Where a write goes. Omit it for a read-only board.
   *
   * A string receives a `POST` whose body is
   * `{ setting_id, name, layer, value, clear, user_id, group_id, visible, enforced }`.
   * Pass a function to write to a REST route of your own shape.
   */
  write?: HttpRoute<WriteRequest>;
  /** Sent on every request. A function is called per request, for a fresh token. */
  headers?: Record<string, string> | (() => Record<string, string> | Promise<Record<string, string>>);
  /** Forwarded to `fetch`, for a session-cookie API. */
  credentials?: RequestCredentials;
  /** Swapped in for tests, or for a framework's instrumented fetch. */
  fetch?: typeof globalThis.fetch;
}

/** Builds a transport over your own HTTP API. */
export function createHttpTransport(options: HttpTransportOptions): SettingsTransport {
  const doFetch = options.fetch ?? globalThis.fetch;

  async function send(spec: HttpRequestSpec, signal?: AbortSignal): Promise<Response> {
    const extra = typeof options.headers === "function" ? await options.headers() : options.headers;
    const hasBody = spec.body !== undefined;

    const response = await doFetch(spec.url, {
      method: spec.method ?? (hasBody ? "POST" : "GET"),
      headers: {
        Accept: "application/json",
        ...(hasBody ? { "Content-Type": "application/json" } : {}),
        ...extra,
        ...spec.headers,
      },
      body: hasBody ? JSON.stringify(spec.body) : undefined,
      credentials: options.credentials,
      signal,
    });

    if (!response.ok) {
      throw new SettingsRequestError(response.status, spec, await readMessage(response));
    }
    return response;
  }

  const transport: SettingsTransport = {
    async resolve(query, signal) {
      const spec = resolveSpec(options.resolve, query, () => ({
        url: appendQuery(routeUrl(options.resolve, query), resolveParams(query)),
      }));
      const response = await send(spec, signal);
      return (await response.json()) as ResolveResponse;
    },
  };

  if (options.write) {
    const route = options.write;
    transport.write = async (request, signal) => {
      const spec = resolveSpec(route, request, () => ({
        url: routeUrl(route, request),
        method: "POST",
        body: writeBody(request),
      }));
      await send(spec, signal);
    };
  }

  return transport;
}

/** A failed request against your own API, with enough context to debug it. */
export class SettingsRequestError extends Error {
  override readonly name = "SettingsRequestError";

  constructor(
    readonly status: number,
    readonly request: HttpRequestSpec,
    readonly detail?: string,
  ) {
    super(
      `${request.method ?? "GET"} ${request.url} failed with ${status}` +
        (detail ? `: ${detail}` : ""),
    );
  }
}

/** The wire body a string `write` route receives. */
export function writeBody(request: WriteRequest): Record<string, unknown> {
  return {
    setting_id: request.setting.id,
    name: request.setting.name,
    layer: request.layer,
    value: request.value ?? null,
    clear: request.value === undefined,
    user_id: request.userId,
    group_id: request.groupId,
    visible: request.visible,
    enforced: request.enforced,
  };
}

/** The query parameters a string `resolve` route receives. */
export function resolveParams(query: ResolveQuery): Record<string, string | string[] | undefined> {
  return {
    user_id: query.userId,
    environment: query.environment,
    platform: query.platform,
    role: query.role,
    group_id: query.groupId,
  };
}

/** Appends parameters, keeping whatever the URL already carried. */
export function appendQuery(
  url: string,
  params: Record<string, string | string[] | undefined>,
): string {
  const [base, existing] = url.split("?", 2);
  const search = new URLSearchParams(existing);

  for (const [key, value] of Object.entries(params)) {
    if (value === undefined) continue;
    for (const one of Array.isArray(value) ? value : [value]) search.append(key, one);
  }

  const query = search.toString();
  return query ? `${base}?${query}` : (base as string);
}

function resolveSpec<T>(
  route: HttpRoute<T>,
  input: T,
  fallback: () => HttpRequestSpec,
): HttpRequestSpec {
  if (typeof route === "string") return fallback();
  const spec = route(input);
  return typeof spec === "string" ? { url: spec } : spec;
}

function routeUrl<T>(route: HttpRoute<T>, input: T): string {
  if (typeof route === "string") return route;
  const spec = route(input);
  return typeof spec === "string" ? spec : spec.url;
}

async function readMessage(response: Response): Promise<string | undefined> {
  try {
    const text = await response.text();
    if (!text) return undefined;
    const parsed: unknown = JSON.parse(text);
    if (parsed && typeof parsed === "object") {
      const body = parsed as { error?: { message?: string }; message?: string };
      return body.error?.message ?? body.message ?? text.slice(0, 200);
    }
    return text.slice(0, 200);
  } catch {
    return undefined;
  }
}

function required(value: string | undefined, layer: string, field: string): string {
  if (!value) {
    throw new Error(
      `writing the ${layer} layer needs a ${field}: pass it to the hook, or set a default on <AppSettingsProvider>`,
    );
  }
  return value;
}

"use client";

/**
 * Reading a resolution.
 *
 * One resolution is one query, keyed by what it was resolved for, so a page
 * with thirty fields makes one request rather than thirty.
 */

import { useCallback } from "react";
import { useQuery, useQueryClient, type QueryKey, type UseQueryResult } from "@tanstack/react-query";
import { SettingsSnapshot, snapshotFrom } from "app-settings-js";

import { useAppSettingsConfig } from "@/registry/app-settings/lib/app-settings/context";
import { appSettingsKeys } from "@/registry/app-settings/lib/app-settings/keys";
import type {
  ResolvedSetting,
  ResolveQuery,
  ResolveResponse,
} from "@/registry/app-settings/lib/app-settings/types";
import type { SettingsQueryConfig } from "@/registry/app-settings/lib/app-settings/context";

/** What to resolve, and how hard to work at keeping it fresh. */
export interface UseSettingsOptions extends ResolveQuery {
  /** Overrides the provider's React Query settings for this resolution. */
  queryConfig?: SettingsQueryConfig;
  /** Skips the request entirely, for a panel that is not open yet. */
  enabled?: boolean;
}

/**
 * The query result, plus the parts a settings page reaches for.
 *
 * An intersection rather than an interface: React Query's result is a union of
 * its loading, error and success shapes, and extending a union is not a thing.
 */
export type UseSettingsResult = UseQueryResult<SettingsSnapshot, Error> & {
  /** The resolution, or undefined before the first one lands. */
  snapshot: SettingsSnapshot | undefined;
  /** Every setting the resolution returned, in the server's order. */
  settings: ResolvedSetting[];
  /** The cache key this resolution lives under, for manual cache work. */
  queryKey: QueryKey;
};

/** Resolves settings and keeps them fresh. */
export function useSettings(options: UseSettingsOptions = {}): UseSettingsResult {
  const config = useAppSettingsConfig();
  const transport = config.transport;

  // Neither of these is memoised: React Query hashes the key structurally, so a
  // fresh-but-equal key is the same cache entry, and a fresh `queryFn` closure
  // is what it expects on every render anyway.
  const query = mergeQuery(config.query, options);
  const queryKey = appSettingsKeys.resolution(query);

  // A snapshot wraps the response without copying it, but it is still a new
  // object each call, so the identity has to come from React Query's own
  // memoisation of `select` rather than from the function body.
  const select = useCallback((response: ResolveResponse) => snapshotFrom(response), []);

  const result = useQuery({
    queryKey,
    queryFn: ({ signal }) => transport.resolve(query, signal),
    select,
    staleTime: 30_000,
    ...config.queryConfig,
    ...options.queryConfig,
    enabled: options.enabled ?? true,
  });

  return {
    ...result,
    snapshot: result.data,
    settings: result.data ? [...result.data.settings] : [],
    queryKey,
  };
}

/**
 * The resolution alone, for a component that only reads.
 *
 * @example
 * const snapshot = useSettingsSnapshot();
 * if (snapshot?.boolean("beta.enabled")) return <BetaBanner />;
 */
export function useSettingsSnapshot(options: UseSettingsOptions = {}): SettingsSnapshot | undefined {
  return useSettings(options).snapshot;
}

/**
 * Refetches resolutions.
 *
 * With no argument every resolution is invalidated, which is what a bulk import
 * or an out-of-band change calls for. With one, only that resolution is.
 */
export function useRefreshSettings(): (query?: ResolveQuery) => Promise<void> {
  const queryClient = useQueryClient();
  const config = useAppSettingsConfig();

  return useCallback(
    async (query?: ResolveQuery) => {
      await queryClient.invalidateQueries({
        queryKey: query
          ? appSettingsKeys.resolution(mergeQuery(config.query, query))
          : appSettingsKeys.resolutions(),
      });
    },
    [queryClient, config.query],
  );
}

/** The provider's defaults with a hook's own overrides laid over them. */
export function mergeQuery(defaults: ResolveQuery, overrides: ResolveQuery = {}): ResolveQuery {
  return {
    userId: overrides.userId ?? defaults.userId,
    environment: overrides.environment ?? defaults.environment,
    platform: overrides.platform ?? defaults.platform,
    role: overrides.role ?? defaults.role,
    groupId: overrides.groupId ?? defaults.groupId,
  };
}

"use client";

/**
 * Reading and writing one setting.
 *
 * A write is applied to the cached resolution before the request goes out and
 * rolled back if it fails, so a control feels instant without ever lying: an
 * enforced value is left where it is, because a group policy would put it back.
 */

import { useCallback, useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";

import { useAppSettingsConfig } from "@/registry/app-settings/lib/app-settings/context";
import {
  isEnforced,
  settingStatus,
  sourceForLayer,
  validateValue,
  withValue,
} from "@/registry/app-settings/lib/app-settings/values";
import type {
  ResolvedSetting,
  ResolveResponse,
  SettingLayer,
  SettingStatus,
  SettingValue,
  ValueProblem,
  WriteRequest,
} from "@/registry/app-settings/lib/app-settings/types";
import {
  useSettings,
  type UseSettingsOptions,
} from "@/registry/app-settings/hooks/app-settings/use-settings";

/** Where a write should land. Every field defaults to the provider's own. */
export interface WriteOptions {
  layer?: SettingLayer;
  /** The user whose personal value is written. Defaults to the resolved user. */
  writeUserId?: string;
  /** The group whose override is written, for the `group` layer. */
  writeGroupId?: string;
  /** `group` layer: whether the user may observe the override. */
  visible?: boolean;
  /** `group` layer: whether the override beats the user's own value. */
  enforced?: boolean;
  /** Check the value against `type_config` before writing. On by default. */
  validate?: boolean;
}

export interface UseSettingOptions extends UseSettingsOptions, WriteOptions {
  /** Called after a write lands and the resolution has been invalidated. */
  onWritten?: (value: SettingValue | undefined, setting: ResolvedSetting) => void;
  /** Called when a write fails, or when local validation rejected the value. */
  onError?: (error: Error) => void;
}

export interface UseSettingResult {
  /** The resolved setting, or undefined while loading or if the role cannot see it. */
  setting: ResolvedSetting | undefined;
  /** The effective value, already optimistic if a write is in flight. */
  value: SettingValue;
  /** Source, override and unset state, for the field chrome. */
  status: SettingStatus | undefined;
  /** The first resolution has not arrived yet. */
  isLoading: boolean;
  /** The resolution failed. */
  error: Error | null;
  /** A write is in flight. */
  isWriting: boolean;
  /** The last write's failure, cleared by the next attempt. */
  writeError: Error | null;
  /** Why the last value offered to {@link UseSettingResult.set} was rejected. */
  problem: ValueProblem | null;
  /** Whether a control should be editable at all. */
  canWrite: boolean;
  /**
   * Writes a value. Resolves `true` when it landed, `false` when local
   * validation rejected it or the request failed — never rejects, so a control's
   * change handler needs no try/catch.
   */
  set: (value: SettingValue) => Promise<boolean>;
  /** Clears this layer, falling back to whatever lies beneath it. */
  clear: () => Promise<boolean>;
  /** Re-resolves, discarding anything optimistic. */
  refresh: () => Promise<void>;
}

/**
 * One setting, ready to bind to a control.
 *
 * @example
 * const { value, set, canWrite } = useSetting("signups.enabled");
 * <Switch checked={value === true} onCheckedChange={set} disabled={!canWrite} />
 */
export function useSetting(name: string, options: UseSettingOptions = {}): UseSettingResult {
  const config = useAppSettingsConfig();
  const queryClient = useQueryClient();
  const [problem, setProblem] = useState<ValueProblem | null>(null);

  const { snapshot, queryKey, isLoading, error } = useSettings(options);
  const setting = snapshot?.get(name);

  const layer = options.layer ?? config.layer;
  const shouldValidate = options.validate ?? config.validate;
  const writable = config.transport.write !== undefined && !config.readOnly;

  const mutation = useMutation<void, Error, SettingValue | undefined, { previous?: ResolveResponse }>({
    mutationFn: async (value) => {
      if (!setting) throw new Error(`no setting named "${name}" is present in this resolution`);
      const write = config.transport.write;
      if (!write) throw new Error("this transport is read-only: it has no write()");

      const request: WriteRequest = {
        setting,
        value,
        layer,
        userId: layer === "personal" ? (options.writeUserId ?? options.userId ?? config.query.userId) : undefined,
        groupId: layer === "group" ? (options.writeGroupId ?? config.writeGroupId) : undefined,
        visible: options.visible ?? config.visible,
        enforced: options.enforced ?? config.enforced,
      };
      await write(request);
    },

    onMutate: async (value) => {
      await queryClient.cancelQueries({ queryKey });
      const previous = queryClient.getQueryData<ResolveResponse>(queryKey);

      // Clearing falls through to a layer only the server knows about, and an
      // enforced value will not move at all. Neither is safe to predict.
      const predictable = value !== undefined && setting !== undefined && !isEnforced(setting);
      if (predictable) {
        queryClient.setQueryData<ResolveResponse>(queryKey, (current) =>
          current ? withValue(current, name, value, sourceForLayer(layer)) : current,
        );
      }

      return { previous };
    },

    onError: (writeError, _value, context) => {
      if (context?.previous) queryClient.setQueryData(queryKey, context.previous);
      options.onError?.(writeError);
    },

    onSuccess: (_data, value) => {
      if (setting) options.onWritten?.(value, setting);
    },

    // The server canonicalises what it stores — a DATETIME comes back in UTC —
    // so the truth always comes from the next resolution.
    onSettled: () => queryClient.invalidateQueries({ queryKey }),
  });

  const write = useCallback(
    async (value: SettingValue | undefined) => {
      if (!setting) return false;

      if (shouldValidate && value !== undefined) {
        const found = validateValue(setting, value);
        setProblem(found);
        if (found) {
          options.onError?.(new Error(`${setting.name}: ${found.message}`));
          return false;
        }
      } else {
        setProblem(null);
      }

      try {
        await mutation.mutateAsync(value);
        return true;
      } catch {
        // The failure is in `writeError`; a control should not have to catch.
        return false;
      }
    },
    [setting, shouldValidate, mutation, options],
  );

  const refresh = useCallback(async () => {
    await queryClient.invalidateQueries({ queryKey });
  }, [queryClient, queryKey]);

  return {
    setting,
    value: setting?.value ?? null,
    status: setting ? settingStatus(setting) : undefined,
    isLoading,
    error: error ?? null,
    isWriting: mutation.isPending,
    writeError: mutation.error,
    problem,
    canWrite: writable && setting !== undefined && !isEnforced(setting),
    set: (value: SettingValue) => write(value),
    clear: () => write(undefined),
    refresh,
  };
}

/**
 * One value, typed by the caller, for a feature check rather than a control.
 *
 * @example
 * const betaEnabled = useSettingValue<boolean>("beta.enabled", false);
 */
export function useSettingValue<T = SettingValue>(
  name: string,
  fallback: T,
  options: UseSettingsOptions = {},
): T {
  const { snapshot } = useSettings(options);
  const setting = snapshot?.get(name);
  if (!setting || setting.source === "UNSET" || setting.value === null) return fallback;
  return setting.value as T;
}

"use client";

/**
 * Editing many settings and saving them together.
 *
 * {@link useSetting} writes on every change, which is right for a switchboard.
 * A form with a Save button wants the opposite: hold the edits locally, show
 * what is dirty, then apply them in one go. That is this hook.
 */

import { useCallback, useMemo, useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";

import { useAppSettingsConfig } from "@/registry/app-settings/lib/app-settings/context";
import {
  controlValue,
  isEnforced,
  validateValue,
  valuesEqual,
} from "@/registry/app-settings/lib/app-settings/values";
import type {
  ResolvedSetting,
  SettingValue,
  ValueProblem,
  WriteRequest,
} from "@/registry/app-settings/lib/app-settings/types";
import {
  useSettings,
  type UseSettingsOptions,
} from "@/registry/app-settings/hooks/app-settings/use-settings";
import type { WriteOptions } from "@/registry/app-settings/hooks/app-settings/use-setting";

export interface UseSettingsDraftOptions extends UseSettingsOptions, WriteOptions {
  /** Only these settings, in this order. Defaults to everything resolved. */
  names?: string[];
  /** Called once every write has been attempted, successful or not. */
  onSaved?: (result: SaveResult) => void;
}

/** What a save actually managed to do. */
export interface SaveResult {
  /** Names written, in the order they were attempted. */
  written: string[];
  /** Names that failed, with the reason each one did. */
  failed: { name: string; error: Error }[];
}

/** Everything a controlled field needs, so a form can spread it. */
export interface DraftField {
  setting: ResolvedSetting;
  value: SettingValue;
  onValueChange: (value: SettingValue) => void;
  /** Edited locally and not yet saved. */
  dirty: boolean;
  /** Why this edit is not savable. */
  problem: ValueProblem | null;
  disabled: boolean;
}

export interface UseSettingsDraftResult {
  /** The settings in scope, in the server's order or the order given. */
  settings: ResolvedSetting[];
  /** Effective values with local edits laid over them, by setting name. */
  values: Record<string, SettingValue>;
  /** Only the local edits. */
  draft: Record<string, SettingValue>;
  /** Names whose draft value differs from the resolved one. */
  dirty: string[];
  isDirty: boolean;
  /** Local validation failures, by setting name. */
  problems: Record<string, ValueProblem>;
  /** At least one edit would be rejected, so saving is blocked. */
  hasProblems: boolean;
  isLoading: boolean;
  error: Error | null;
  isSaving: boolean;
  /** The last save that had failures, for a summary above the form. */
  lastResult: SaveResult | null;
  /** Records an edit. Validates it immediately but writes nothing. */
  setValue: (name: string, value: SettingValue) => void;
  /** Drops one edit, or every edit when called with no name. */
  revert: (name?: string) => void;
  /** Writes every dirty value. Never rejects: read the result. */
  save: () => Promise<SaveResult>;
  /** Everything one field needs, ready to spread onto `<SettingField>`. */
  field: (name: string) => DraftField | undefined;
}

/**
 * A local draft over a resolution.
 *
 * @example
 * const draft = useSettingsDraft({ names: ["rate.limit", "signups.enabled"] });
 *
 * <SettingField {...draft.field("rate.limit")!} />
 * <Button disabled={!draft.isDirty || draft.hasProblems} onClick={draft.save}>
 *   Save {draft.dirty.length} changes
 * </Button>
 */
export function useSettingsDraft(
  options: UseSettingsDraftOptions = {},
): UseSettingsDraftResult {
  const config = useAppSettingsConfig();
  const queryClient = useQueryClient();
  const { snapshot, queryKey, isLoading, error } = useSettings(options);

  const [draft, setDraft] = useState<Record<string, SettingValue>>({});
  const [problems, setProblems] = useState<Record<string, ValueProblem>>({});
  const [lastResult, setLastResult] = useState<SaveResult | null>(null);

  const layer = options.layer ?? config.layer;
  const shouldValidate = options.validate ?? config.validate;
  const writable = config.transport.write !== undefined && !config.readOnly;

  const settings = useMemo(() => {
    if (!snapshot) return [];
    if (!options.names) return [...snapshot.settings];
    return options.names
      .map((name) => snapshot.get(name))
      .filter((setting): setting is ResolvedSetting => setting !== undefined);
  }, [snapshot, options.names]);

  const values = useMemo(() => {
    const merged: Record<string, SettingValue> = {};
    for (const setting of settings) {
      merged[setting.name] =
        setting.name in draft ? draft[setting.name] : controlValue(setting);
    }
    return merged;
  }, [settings, draft]);

  const dirty = useMemo(
    () =>
      settings
        .filter(
          (setting) =>
            setting.name in draft && !valuesEqual(draft[setting.name], setting.value),
        )
        .map((setting) => setting.name),
    [settings, draft],
  );

  const setValue = useCallback(
    (name: string, value: SettingValue) => {
      setDraft((current) => ({ ...current, [name]: value }));

      if (!shouldValidate) return;
      const setting = snapshot?.get(name);
      const found = setting ? validateValue(setting, value) : null;

      setProblems((current) => {
        if (!found) {
          if (!(name in current)) return current;
          const { [name]: _removed, ...rest } = current;
          return rest;
        }
        return { ...current, [name]: found };
      });
    },
    [shouldValidate, snapshot],
  );

  const revert = useCallback((name?: string) => {
    if (name === undefined) {
      setDraft({});
      setProblems({});
      return;
    }
    setDraft(({ [name]: _dropped, ...rest }) => rest);
    setProblems(({ [name]: _cleared, ...rest }) => rest);
  }, []);

  const mutation = useMutation<SaveResult, Error, void>({
    mutationFn: async () => {
      const write = config.transport.write;
      if (!write) throw new Error("this transport is read-only: it has no write()");

      const result: SaveResult = { written: [], failed: [] };

      // Sequential on purpose: a failure halfway through leaves a state a
      // reader can reason about, and the API is not a bulk endpoint.
      for (const name of dirty) {
        const setting = snapshot?.get(name);
        if (!setting) continue;

        const request: WriteRequest = {
          setting,
          value: draft[name],
          layer,
          userId:
            layer === "personal"
              ? (options.writeUserId ?? options.userId ?? config.query.userId)
              : undefined,
          groupId: layer === "group" ? (options.writeGroupId ?? config.writeGroupId) : undefined,
          visible: options.visible ?? config.visible,
          enforced: options.enforced ?? config.enforced,
        };

        try {
          await write(request);
          result.written.push(name);
        } catch (caught) {
          result.failed.push({
            name,
            error: caught instanceof Error ? caught : new Error(String(caught)),
          });
        }
      }

      return result;
    },

    onSuccess: (result) => {
      setLastResult(result);
      // Keep the edits that failed, so the form still shows what to retry.
      setDraft((current) => {
        const remaining = { ...current };
        for (const name of result.written) delete remaining[name];
        return remaining;
      });
      options.onSaved?.(result);
    },

    onSettled: () => queryClient.invalidateQueries({ queryKey }),
  });

  const save = useCallback(async () => {
    if (Object.keys(problems).length > 0) {
      const result: SaveResult = {
        written: [],
        failed: Object.entries(problems).map(([name, problem]) => ({
          name,
          error: new Error(`${name}: ${problem.message}`),
        })),
      };
      setLastResult(result);
      return result;
    }

    try {
      return await mutation.mutateAsync();
    } catch (caught) {
      const result: SaveResult = {
        written: [],
        failed: dirty.map((name) => ({
          name,
          error: caught instanceof Error ? caught : new Error(String(caught)),
        })),
      };
      setLastResult(result);
      return result;
    }
  }, [problems, mutation, dirty]);

  const field = useCallback(
    (name: string): DraftField | undefined => {
      const setting = settings.find((candidate) => candidate.name === name);
      if (!setting) return undefined;

      return {
        setting,
        value: values[name] ?? controlValue(setting),
        onValueChange: (value: SettingValue) => setValue(name, value),
        dirty: dirty.includes(name),
        problem: problems[name] ?? null,
        disabled: !writable || isEnforced(setting),
      };
    },
    [settings, values, dirty, problems, writable, setValue],
  );

  return {
    settings,
    values,
    draft,
    dirty,
    isDirty: dirty.length > 0,
    problems,
    hasProblems: Object.keys(problems).length > 0,
    isLoading,
    error: error ?? null,
    isSaving: mutation.isPending,
    lastResult,
    setValue,
    revert,
    save,
    field,
  };
}

"use client";

import * as React from "react";
import {
  QueryClient,
  QueryClientContext,
  QueryClientProvider,
} from "@tanstack/react-query";

import {
  AppSettingsContext,
  type AppSettingsConfig,
  type SettingsQueryConfig,
} from "@/registry/app-settings/lib/app-settings/context";
import type {
  ResolveQuery,
  SettingLayer,
  SettingsTransport,
} from "@/registry/app-settings/lib/app-settings/types";

export interface AppSettingsProviderProps extends ResolveQuery {
  /**
   * Where settings come from.
   *
   * `transportFromClient(client)` for a board that holds an API key;
   * `createHttpTransport({ ... })` for one that goes through your own API.
   */
  transport: SettingsTransport;
  /**
   * Which layer writes land in.
   *
   * Defaults to `personal` when a `userId` is given and `server` otherwise,
   * which is the right guess for a user's own preferences page and for an
   * operator's switchboard respectively.
   */
  layer?: SettingLayer;
  /** The group a `group`-layer write targets. */
  writeGroupId?: string;
  /** `group` layer: whether the user may observe the override. */
  visible?: boolean;
  /** `group` layer: whether the override beats the user's own value. */
  enforced?: boolean;
  /** Renders every control disabled, for a board someone may only look at. */
  readOnly?: boolean;
  /** Check values against `type_config` before writing. On by default. */
  validate?: boolean;
  /** React Query defaults for every resolution under this provider. */
  queryConfig?: SettingsQueryConfig;
  /**
   * A `QueryClient` to use when the app does not already have one.
   *
   * If a `QueryClientProvider` is already above this component, that client is
   * used and this is ignored. Otherwise one is created so the components work
   * in an app that has not adopted React Query yet.
   */
  queryClient?: QueryClient;
  children?: React.ReactNode;
}

/**
 * Configures every App Settings hook and component below it.
 *
 * @example
 * const transport = transportFromClient(
 *   new AppSettingsClient({ baseUrl, apiKey, environment: "production" }),
 * );
 *
 * <AppSettingsProvider transport={transport} layer="server">
 *   <SettingList groupBy="prefix" />
 * </AppSettingsProvider>
 */
export function AppSettingsProvider({
  transport,
  userId,
  environment,
  platform,
  role,
  groupId,
  layer,
  writeGroupId,
  visible,
  enforced,
  readOnly = false,
  validate = true,
  queryConfig,
  queryClient,
  children,
}: AppSettingsProviderProps) {
  // Arrays and the query config are commonly written inline, so the identity of
  // `config` is pinned to their contents rather than to the object passed in.
  const platformSeed = JSON.stringify(platform ?? null);
  const groupSeed = JSON.stringify(groupId ?? null);
  const queryConfigSeed = JSON.stringify(queryConfig ?? null);

  const config = React.useMemo<AppSettingsConfig>(
    () => ({
      transport,
      query: { userId, environment, platform, role, groupId },
      layer: layer ?? (userId ? "personal" : "server"),
      writeGroupId: writeGroupId ?? firstOf(groupId),
      visible,
      enforced,
      readOnly,
      validate,
      queryConfig: queryConfig ?? {},
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps -- seeds stand in for the inline array and object props above.
    [
      transport,
      userId,
      environment,
      role,
      platformSeed,
      groupSeed,
      layer,
      writeGroupId,
      visible,
      enforced,
      readOnly,
      validate,
      queryConfigSeed,
    ],
  );

  return (
    <AppSettingsContext.Provider value={config}>
      <EnsureQueryClient client={queryClient}>{children}</EnsureQueryClient>
    </AppSettingsContext.Provider>
  );
}

/**
 * Wraps the tree in a `QueryClientProvider` only when the app has none.
 *
 * Mounting a second one would give these components their own cache, which is
 * the bug where a write here never updates a list rendered by the app's own
 * query elsewhere.
 */
function EnsureQueryClient({
  client,
  children,
}: {
  client?: QueryClient;
  children?: React.ReactNode;
}) {
  const existing = React.useContext(QueryClientContext);
  const [fallback] = React.useState(() => client ?? new QueryClient());

  if (existing) return <>{children}</>;
  return <QueryClientProvider client={client ?? fallback}>{children}</QueryClientProvider>;
}

function firstOf(value: string | string[] | undefined): string | undefined {
  if (value === undefined) return undefined;
  return Array.isArray(value) ? value[0] : value;
}
